def email_allowed(email: str, settings: Settings) -> bool:
    if not _EMAIL_RE.match(email or ""):
        return False
    domains = settings.allowed_domains
    if not domains:
        return True
    domain = email.rsplit("@", 1)[-1].lower()
    return any(domain == d or domain.endswith("." + d) for d in domains)


